use bcrypt::{hash, verify};

// Example of hashing a password
fn hash_password(password: &str) -> String {
    hash(password, 4).unwrap()
}

// Example of verifying a password
fn verify_password(password: &str, hashed: &str) -> bool {
    verify(password, hashed).unwrap()
}

fn main() {
    let password = "mySecretPassword";
    let hashed_password = hash_password(password);
    assert!(verify_password(password, &hashed_password));
    println!("Password hashing and verification successful.");
}
